package com.tecsup.producto.service;
import com.tecsup.producto.dto.ProductoRequest; import com.tecsup.producto.model.Producto; import com.tecsup.producto.repository.ProductoRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@Service public class ProductoService { private final ProductoRepository repo; private final RestClient client;
 public ProductoService(ProductoRepository repo,RestClient.Builder builder,@Value("${producto.url-categorias}") String url){this.repo=repo;this.client=builder.baseUrl(url).build();}
 public List<Producto> listar(){return repo.findAll();} public Producto obtener(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Producto no encontrado"));}
 private void aplicar(Producto p,ProductoRequest d){try{client.get().uri("/api/categorias/{id}",d.categoriaId()).retrieve().toBodilessEntity();}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Categoría no disponible: "+d.categoriaId());} p.setNombre(d.nombre());p.setPrecio(d.precio());p.setStock(d.stock());p.setCategoriaId(d.categoriaId());}
 public Producto crear(ProductoRequest d){Producto p=new Producto();aplicar(p,d);return repo.save(p);} public Producto actualizar(Long id,ProductoRequest d){Producto p=obtener(id);aplicar(p,d);return repo.save(p);} public void eliminar(Long id){repo.delete(obtener(id));}}
